CREATE OR REPLACE FUNCTION private.user_can_view_project(p_actor_user_id uuid, p_project_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_project record;
begin
  select p.company_id
    into v_project
    from public.projects p
   where p.id = p_project_id
     and p.deleted_at is null;

  if not found or not exists (
    select 1
      from public.users u
     where u.id = p_actor_user_id
       and u.company_id = v_project.company_id
       and u.deleted_at is null
       and coalesce(u.is_active, false)
  ) then
    return false;
  end if;

  if public.has_permission(p_actor_user_id, 'projects.view', 'all') then
    return true;
  end if;

  if not public.has_permission(
    p_actor_user_id,
    'projects.view',
    'assigned'
  ) then
    return false;
  end if;

  return exists (
    select 1
      from public.project_tasks pt
     where pt.project_id = p_project_id
       and pt.deleted_at is null
       and p_actor_user_id::text = any(
         coalesce(pt.team_member_ids, array[]::text[])
       )
  ) or exists (
    select 1
      from public.project_notes pn
     where pn.project_id = p_project_id::text
       and pn.deleted_at is null
       and p_actor_user_id::text = any(
         coalesce(pn.mentioned_user_ids, array[]::text[])
       )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.move_opportunity_stage(p_opportunity_id uuid, p_to_stage text, p_user_id uuid, p_win_probability integer DEFAULT NULL::integer)
 RETURNS opportunities
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_company_id uuid;
  v_from_stage text;
  v_prior_entered_at timestamptz;
  v_now timestamptz := clock_timestamp();
  v_actor_user_id uuid;
  v_updated public.opportunities;
begin
  if p_opportunity_id is null or nullif(btrim(p_to_stage), '') is null then
    raise exception 'opportunity and target stage are required'
      using errcode = '22023';
  end if;

  select opportunity.company_id
  into v_company_id
  from public.opportunities opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.deleted_at is null;

  if not found then
    raise exception 'opportunity_not_found'
      using errcode = 'P0002';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
    and p_user_id is not null
    and p_user_id is distinct from private.get_current_user_id()
  then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;
  v_actor_user_id := case
    when coalesce(auth.role(), '') = 'service_role' then p_user_id
    else coalesce(p_user_id, private.get_current_user_id())
  end;

  perform private.lock_lead_assignment_company(v_company_id);

  select opportunity.stage, opportunity.stage_entered_at
  into v_from_stage, v_prior_entered_at
  from public.opportunities opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.company_id = v_company_id
    and opportunity.deleted_at is null
  for update;

  if not found then
    raise exception 'opportunity_not_found'
      using errcode = 'P0002';
  end if;

  if v_from_stage = p_to_stage then
    select opportunity.*
    into v_updated
    from public.opportunities opportunity
    where opportunity.id = p_opportunity_id;
    return v_updated;
  end if;

  perform set_config('ops.lifecycle_source', 'manual_stage_change', true);
  perform set_config(
    'ops.lifecycle_actor_user_id',
    coalesce(v_actor_user_id::text, ''),
    true
  );

  update public.opportunities opportunity
  set stage = p_to_stage,
      stage_entered_at = v_now,
      win_probability = coalesce(
        p_win_probability,
        opportunity.win_probability
      ),
      stage_manually_set = true,
      updated_at = v_now
  where opportunity.id = p_opportunity_id
    and opportunity.company_id = v_company_id
    and opportunity.deleted_at is null
  returning opportunity.* into v_updated;

  insert into public.stage_transitions (
    company_id,
    opportunity_id,
    from_stage,
    to_stage,
    transitioned_at,
    transitioned_by,
    duration_in_stage
  ) values (
    v_company_id,
    p_opportunity_id,
    v_from_stage,
    p_to_stage,
    v_now,
    v_actor_user_id,
    case
      when v_prior_entered_at is null then null
      else v_now - v_prior_entered_at
    end
  );

  return v_updated;
end;
$function$
